import { test, expect } from '@playwright/test';

test.describe('Onboarding Tour Modal Navigation', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/onboarding');
  });

  test('should navigate through onboarding steps successfully', async ({ page }) => {
    // Open the onboarding tour modal
    const openButton = page.getByRole('button', { name: /open tour/i });
    await openButton.click();
    const tourModal = page.locator('[data-testid="onboarding-tour-modal"]');
    await expect(tourModal).toBeVisible();

    // Verify initial step is displayed
    const stepOne = page.getByRole('heading', { name: /step 1/i });
    await expect(stepOne).toBeVisible();

    // Verify step content is visible
    const stepOneContent = page.getByText(/welcome to our app/i);
    await expect(stepOneContent).toBeVisible();

    // Click the "Next" button to advance to step 2
    const nextButton = page.getByRole('button', { name: /next/i });
    await nextButton.click();

    // Verify step 2 is now visible
    const stepTwo = page.getByRole('heading', { name: /step 2/i });
    await expect(stepTwo).toBeVisible();

    // Verify step 2 content is visible
    const stepTwoContent = page.getByText(/how to use features/i);
    await expect(stepTwoContent).toBeVisible();

    // Click the "Next" button to advance to step 3
    await nextButton.click();

    // Verify step 3 is now visible
    const stepThree = page.getByRole('heading', { name: /step 3/i });
    await expect(stepThree).toBeVisible();

    // Verify step 3 content is visible
    const stepThreeContent = page.getByText(/sign up/i);
    await expect(stepThreeContent).toBeVisible();

    // Click the "Finish" button to close the modal
    const finishButton = page.getByRole('button', { name: /finish/i });
    await finishButton.click();

    // Verify modal is closed
    await expect(tourModal).not.toBeVisible();

    // Verify welcome message is displayed
    const welcomeMessage = page.getByText(/thank you for completing the tour/i);
    await expect(welcomeMessage).toBeVisible();
  });

  test('should handle navigation failure and retry', async ({ page }) => {
    // Open the onboarding tour modal
    const openButton = page.getByRole('button', { name: /open tour/i });
    await openButton.click();
    const tourModal = page.locator('[data-testid="onboarding-tour-modal"]');
    await expect(tourModal).toBeVisible();

    // Verify initial step is displayed
    const stepOne = page.getByRole('heading', { name: /step 1/i });
    await expect(stepOne).toBeVisible();

    // Verify step content is visible
    const stepOneContent = page.getByText(/welcome to our app/i);
    await expect(stepOneContent).toBeVisible();

    // Click the "Next" button to advance to step 2
    const nextButton = page.getByRole('button', { name: /next/i });
    await nextButton.click();

    // Verify step 2 is now visible
    const stepTwo = page.getByRole('heading', { name: /step 2/i });
    await expect(stepTwo).toBeVisible();

    // Verify step 2 content is visible
    const stepTwoContent = page.getByText(/how to use features/i);
    await expect(stepTwoContent).toBeVisible();

    // Click the "Next" button to advance to step 3
    await nextButton.click();

    // Verify step 3 is now visible
    const stepThree = page.getByRole('heading', { name: /step 3/i });
    await expect(stepThree).toBeVisible();

    // Verify step 3 content is visible
    const stepThreeContent = page.getByText(/sign up/i);
    await expect(stepThreeContent).toBeVisible();

    // Click the "Finish" button to close the modal
    const finishButton = page.getByRole('button', { name: /finish/i });
    await finishButton.click();

    // Verify modal is closed
    await expect(tourModal).not.toBeVisible();

    // Verify welcome message is displayed
    const welcomeMessage = page.getByText(/thank you for completing the tour/i);
    await expect(welcomeMessage).toBeVisible();

    // Introduce a navigation failure by clicking the "Next" button again
    await nextButton.click();

    // Verify error message is displayed
    const errorMessage = page.getByText(/navigation error/i);
    await expect(errorMessage).toBeVisible();

    // Verify retry button is visible
    const retryButton = page.getByRole('button', { name: /retry/i });
    await expect(retryButton).toBeVisible();

    // Click the retry button
    await retryButton.click();

    // Verify step 3 content is still visible
    await expect(stepThreeContent).toBeVisible();

    // Verify welcome message is still displayed
    await expect(welcomeMessage).toBeVisible();
  });
});
